import sys
from subprocess import run # that's how we run our commands now
import gi
gi.require_version('Gtk', '4.0')
gi.require_version('Adw', '1')
from gi.repository import Gtk,Adw



class NotepadGUI(Gtk.Application):
    Adw.init()
    def do_activate(self):
        # Load the UI file generated by Cambalache
        builder = Gtk.Builder.new_from_file("NoteAPI_GUI_Test.ui")
        
        # Get the button object by its ID defined in Cambalache
        self.button = builder.get_object("getnotes_button")
        self.note_output = builder.get_object("text_output")
        # Connect the 'clicked' signal to your Python function
        self.button.connect("clicked", self.on_button_clicked)
        
        # Show the window
        window = builder.get_object("window_id")
        self.add_window(window)
        window.present()

    def on_button_clicked(self, button):
        # This function executes when the button is clicked
        result = run(['curl', '-X', 'GET', '127.0.0.1:8000/getnotes'],capture_output=True,text=True)
        self.note_output.get_buffer().set_text(result.stdout)

app = NotepadGUI(application_id="com.example.app")
app.run(sys.argv)